300		/**
301		 * Generates the URI to use to generate a project represented by this request.
302		 * @param metadata the metadata that describes the service
303		 * @return the project generation URI
304		 */
305		URI generateUrl(InitializrServiceMetadata metadata) {
306			try {
307				URIBuilder builder = new URIBuilder(this.serviceUrl);
308				ProjectType projectType = determineProjectType(metadata);
309				builder.setPath(resolvePath(builder.getPath(), projectType.getAction()));
310				setParameter(builder, "dependencies", this.dependencies.isEmpty()
311						? null : StringUtils.collectionToCommaDelimitedString(this.dependencies));
312				setParameter(builder, "groupId", this.groupId);
313				setParameter(builder, "artifactId", resolveArtifactId());
314				setParameter(builder, "version", this.version);
315				setParameter(builder, "name", this.name);
316				setParameter(builder, "description", this.description);
317				setParameter(builder, "packageName", this.packageName);
318				builder.setParameter("type", projectType.getId());
319				setParameter(builder, "packaging", this.packaging);
320				setParameter(builder, "javaVersion", this.javaVersion);
321				setParameter(builder, "language", this.language);
322				setParameter(builder, "bootVersion", this.bootVersion);
323				return builder.build();
324			}
325			catch (URISyntaxException ex) {
326				throw new ReportableException("Invalid service URL (" + ex.getMessage() + ")");
327			}
328		}
