330		protected ProjectType determineProjectType(InitializrServiceMetadata metadata) {
331			if (this.type != null) {
332				ProjectType result = metadata.getProjectTypes().get(this.type);
333				if (result == null) {
334					throw new ReportableException(
335							("No project type with id '" + this.type + "' - check the service capabilities (--list)"));
336				}
337				return result;
338			}
339			if (isDetectType()) {
340				Map<String, ProjectType> types = new HashMap<>(metadata.getProjectTypes());
341				if (this.build != null) {
342					filter(types, "build", this.build);
343				}
344				if (this.format != null) {
345					filter(types, "format", this.format);
346				}
347				if (types.size() == 1) {
348					return types.values().iterator().next();
349				}
350				if (types.isEmpty()) {
351					throw new ReportableException("No type found with build '" + this.build + "' and format '" + this.format
352							+ "' check the service capabilities (--list)");
353				}
354				throw new ReportableException("Multiple types found with build '" + this.build + "' and format '"
355						+ this.format + "' use --type with a more specific value " + types.keySet());
356			}
357			ProjectType defaultType = metadata.getDefaultType();
358			if (defaultType == null) {
359				throw new ReportableException(("No project type is set and no default is defined. "
360						+ "Check the service capabilities (--list)"));
361			}
362			return defaultType;
363		}
