365		/**
366		 * Resolve the artifactId to use or {@code null} if it should not be customized.
367		 * @return the artifactId
368		 */
369		protected @Nullable String resolveArtifactId() {
370			if (this.artifactId != null) {
371				return this.artifactId;
372			}
373			if (this.output != null) {
374				int i = this.output.lastIndexOf('.');
375				return (i != -1) ? this.output.substring(0, i) : this.output;
376			}
377			return null;
378		}
