 32	/**
 33	 * Define the metadata available for a particular service instance.
 34	 *
 35	 * @author Stephane Nicoll
 36	 */
 37	class InitializrServiceMetadata {
 38	
 39		private static final String DEPENDENCIES_EL = "dependencies";
 40	
 41		private static final String TYPE_EL = "type";
 42	
 43		private static final String VALUES_EL = "values";
 44	
 45		private static final String NAME_ATTRIBUTE = "name";
 46	
 47		private static final String ID_ATTRIBUTE = "id";
 48	
 49		private static final String DESCRIPTION_ATTRIBUTE = "description";
 50	
 51		private static final String ACTION_ATTRIBUTE = "action";
 52	
 53		private static final String DEFAULT_ATTRIBUTE = "default";
 54	
 55		private static final String TAGS_ELEMENT = "tags";
 56	
 57		private final Map<String, Dependency> dependencies;
 58	
 59		private final MetadataHolder<String, ProjectType> projectTypes;
 60	
 61		private final Map<String, String> defaults;
 62	
 63		/**
 64		 * Creates a new instance using the specified root {@link JSONObject}.
 65		 * @param root the root JSONObject
 66		 * @throws JSONException on JSON parsing failure
 67		 */
 68		InitializrServiceMetadata(JSONObject root) throws JSONException {
 69			this.dependencies = parseDependencies(root);
 70			this.projectTypes = parseProjectTypes(root);
 71			this.defaults = Collections.unmodifiableMap(parseDefaults(root));
 72		}
 73	
 74		InitializrServiceMetadata(ProjectType defaultProjectType) {
 75			this.dependencies = new HashMap<>();
 76			this.projectTypes = new MetadataHolder<>();
 77			this.projectTypes.getContent().put(defaultProjectType.getId(), defaultProjectType);
 78			this.projectTypes.setDefaultItem(defaultProjectType);
 79			this.defaults = Collections.emptyMap();
 80		}
 81	
 82		/**
 83		 * Return the dependencies supported by the service.
 84		 * @return the supported dependencies
 85		 */
 86		Collection<Dependency> getDependencies() {
 87			return Collections.unmodifiableCollection(this.dependencies.values());
 88		}
 89	
 90		/**
 91		 * Return the dependency with the specified id or {@code null} if no such dependency
 92		 * exists.
 93		 * @param id the id
 94		 * @return the dependency or {@code null}
 95		 */
 96		@Nullable Dependency getDependency(String id) {
 97			return this.dependencies.get(id);
 98		}
 99	
100		/**
101		 * Return the project types supported by the service.
102		 * @return the supported project types
103		 */
104		Map<String, ProjectType> getProjectTypes() {
105			return Collections.unmodifiableMap(this.projectTypes.getContent());
106		}
107	
108		/**
109		 * Return the default type to use or {@code null} if the metadata does not define any
110		 * default.
111		 * @return the default project type or {@code null}
112		 */
113		@Nullable ProjectType getDefaultType() {
114			if (this.projectTypes.getDefaultItem() != null) {
115				return this.projectTypes.getDefaultItem();
116			}
117			String defaultTypeId = getDefaults().get("type");
118			if (defaultTypeId != null) {
119				return this.projectTypes.getContent().get(defaultTypeId);
120			}
121			return null;
122		}
123	
124		/**
125		 * Returns the defaults applicable to the service.
126		 * @return the defaults of the service
127		 */
128		Map<String, String> getDefaults() {
129			return this.defaults;
130		}
131	
132		private Map<String, Dependency> parseDependencies(JSONObject root) throws JSONException {
133			Map<String, Dependency> result = new HashMap<>();
134			if (!root.has(DEPENDENCIES_EL)) {
135				return result;
136			}
137			JSONObject dependencies = root.getJSONObject(DEPENDENCIES_EL);
138			JSONArray array = dependencies.getJSONArray(VALUES_EL);
139			for (int i = 0; i < array.length(); i++) {
140				JSONObject group = array.getJSONObject(i);
141				parseGroup(group, result);
142			}
143			return result;
144		}
145	
146		private MetadataHolder<String, ProjectType> parseProjectTypes(JSONObject root) throws JSONException {
147			MetadataHolder<String, ProjectType> result = new MetadataHolder<>();
148			if (!root.has(TYPE_EL)) {
149				return result;
150			}
151			JSONObject type = root.getJSONObject(TYPE_EL);
152			JSONArray array = type.getJSONArray(VALUES_EL);
153			String defaultType = (type.has(DEFAULT_ATTRIBUTE) ? type.getString(DEFAULT_ATTRIBUTE) : null);
154			for (int i = 0; i < array.length(); i++) {
155				JSONObject typeJson = array.getJSONObject(i);
156				ProjectType projectType = parseType(typeJson, defaultType);
157				result.getContent().put(projectType.getId(), projectType);
158				if (projectType.isDefaultType()) {
159					result.setDefaultItem(projectType);
160				}
161			}
162			return result;
163		}
164	
165		private Map<String, String> parseDefaults(JSONObject root) throws JSONException {
166			Map<String, String> result = new HashMap<>();
167			Iterator<?> keys = root.keys();
168			while (keys.hasNext()) {
169				String key = (String) keys.next();
170				Object o = root.get(key);
171				if (o instanceof JSONObject child) {
172					if (child.has(DEFAULT_ATTRIBUTE)) {
173						result.put(key, child.getString(DEFAULT_ATTRIBUTE));
174					}
175				}
176			}
177			return result;
178		}
179	
180		private void parseGroup(JSONObject group, Map<String, Dependency> dependencies) throws JSONException {
181			if (group.has(VALUES_EL)) {
182				JSONArray content = group.getJSONArray(VALUES_EL);
183				for (int i = 0; i < content.length(); i++) {
184					Dependency dependency = parseDependency(content.getJSONObject(i));
185					dependencies.put(dependency.getId(), dependency);
186				}
187			}
188		}
189	
190		private Dependency parseDependency(JSONObject object) throws JSONException {
191			String id = getStringValue(object, ID_ATTRIBUTE, null);
192			String name = getStringValue(object, NAME_ATTRIBUTE, null);
193			String description = getStringValue(object, DESCRIPTION_ATTRIBUTE, null);
194			return new Dependency(id, name, description);
195		}
196	
197		private ProjectType parseType(JSONObject object, @Nullable String defaultId) throws JSONException {
198			String id = getStringValue(object, ID_ATTRIBUTE, null);
199			String name = getStringValue(object, NAME_ATTRIBUTE, null);
200			String action = getStringValue(object, ACTION_ATTRIBUTE, null);
201			Assert.state(id != null, "'id' must not be null");
202			boolean defaultType = id.equals(defaultId);
203			Map<String, String> tags = new HashMap<>();
204			if (object.has("tags")) {
205				JSONObject jsonTags = object.getJSONObject(TAGS_ELEMENT);
206				tags.putAll(parseStringItems(jsonTags));
207			}
208			Assert.state(name != null, "'name' must not be null");
209			Assert.state(action != null, "'action' must not be null");
210			return new ProjectType(id, name, action, defaultType, tags);
211		}
212	
213		private @Nullable String getStringValue(JSONObject object, String name, @Nullable String defaultValue)
214				throws JSONException {
215			return object.has(name) ? object.getString(name) : defaultValue;
216		}
217	
218		private Map<String, String> parseStringItems(JSONObject json) throws JSONException {
219			Map<String, String> result = new HashMap<>();
220			for (Iterator<?> iterator = json.keys(); iterator.hasNext();) {
221				String key = (String) iterator.next();
222				Object value = json.get(key);
223				if (value instanceof String string) {
224					result.put(key, string);
225				}
226			}
227			return result;
228		}
