101		private static InitializrServiceMetadata createInstance(String version) throws JSONException {
102			try {
103				return new InitializrServiceMetadata(readJson(version));
104			}
105			catch (IOException ex) {
106				throw new IllegalStateException("Failed to read json", ex);
107			}
108		}
109	
110		private static JSONObject readJson(String version) throws IOException, JSONException {
111			Resource resource = new ClassPathResource("metadata/service-metadata-" + version + ".json");
112			try (InputStream stream = resource.getInputStream()) {
113				return new JSONObject(StreamUtils.copyToString(stream, StandardCharsets.UTF_8));
114			}
115		}
